struct P{a:u32,b:u32}fn transfer<T>(a:&[T;4],b:&mut[T;4],n:usize){let mut i=0usize;while i<n{unsafe{core::ptr::write(&raw mut b[i],core::ptr::read(&raw const a[i]));}i=i+1;}}fn main(){let a=[P{a:2,b:3},P{a:5,b:7},P{a:11,b:13},P{a:17,b:19}];let mut b=[P{a:23,b:29},P{a:31,b:37},P{a:41,b:43},P{a:47,b:53}];transfer(&a,&mut b,0);check(b[0].a==23);check(b[3].b==53);transfer(&a,&mut b,3);check(b[0].a==2);check(b[1].b==7);check(b[2].b==13);check(b[3].a==47);check(a[2].a==11);}
